layouts.css:
.aha-header-section-hero-split{
  --aha-header-section-hero-split-surface:var(--aha-white);
  --aha-header-section-hero-split-ink:var(--aha-text-default);
  --aha-header-section-hero-split-ink-secondary:var(--aha-text-secondary);
  --aha-header-section-hero-split-star:var(--aha-color-primary);
  --aha-header-section-hero-split-frame:var(--aha-border-default);
  --aha-header-section-hero-split-media-bg:var(--aha-bg-container-secondary);
  --aha-header-section-hero-split-focus:var(--aha-focus);
  container:aha-header-section-hero-split / inline-size;
  position:relative;overflow:hidden;
  font-family:var(--aha-font-product);
  background:var(--aha-header-section-hero-split-surface);
  color:var(--aha-header-section-hero-split-ink);
}
.aha-header-section-hero-split--brand{
  --aha-header-section-hero-split-surface:var(--aha-vivid-pink-100);
  --aha-header-section-hero-split-ink:var(--aha-text-inverse);
  --aha-header-section-hero-split-ink-secondary:var(--aha-text-inverse);
  --aha-header-section-hero-split-star:var(--aha-text-inverse);
  --aha-header-section-hero-split-frame:var(--aha-vivid-pink-dark);
  --aha-header-section-hero-split-focus:var(--aha-white);
}
.aha-header-section-hero-split *{box-sizing:border-box}
:where(.aha-header-section-hero-split) :is(h1,h2,p,ul,form,figure){margin:0;padding:0}
:where(.aha-header-section-hero-split) ul{list-style:none}
.aha-header-section-hero-split__inner{max-width:1280px;margin:0 auto;padding:var(--aha-section-space-block) var(--aha-space-32)}
.aha-header-section-hero-split__split{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:var(--aha-section-space-header);align-items:center}
.aha-header-section-hero-split__copy{display:flex;flex-direction:column;align-items:flex-start;max-width:640px}
.aha-header-section-hero-split__title{
  font-size:var(--aha-size-h1);font-weight:var(--aha-weight-semibold);line-height:var(--aha-line-height-heading);
  letter-spacing:var(--aha-letter-spacing-headlines);
  color:var(--aha-header-section-hero-split-ink);
}
.aha-header-section-hero-split__text{
  margin-top:var(--aha-space-24);
  font-size:var(--aha-size-xl);font-weight:var(--aha-weight-regular);line-height:var(--aha-line-height-body);
  letter-spacing:var(--aha-letter-spacing-paragraph);
  color:var(--aha-header-section-hero-split-ink-secondary);
}
.aha-header-section-hero-split__actions{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);margin-top:var(--aha-space-32)}
.aha-header-section-hero-split__form{display:flex;flex-wrap:wrap;gap:var(--aha-space-12);width:100%;max-width:480px;margin-top:var(--aha-space-32)}
.aha-header-section-hero-split__field{display:flex;flex:1 1 240px;min-width:0}
.aha-header-section-hero-split__input{
  width:100%;height:var(--aha-control-height-button-xl);padding:0 var(--aha-space-16);
  border:1px solid var(--aha-border-input);border-radius:var(--aha-radius-default);
  background:var(--aha-white);color:var(--aha-text-default);
  font-family:inherit;font-size:var(--aha-size-l);
  transition:border-color var(--aha-motion-mid) var(--aha-ease-in-out);
}
.aha-header-section-hero-split__input::placeholder{color:var(--aha-text-placeholder);opacity:1}
.aha-header-section-hero-split__input:hover{border-color:var(--aha-border-hover)}
.aha-header-section-hero-split__input:focus{outline:none;border-color:var(--aha-border-focus)}
.aha-header-section-hero-split__input:focus-visible{outline:var(--aha-space-2) solid var(--aha-header-section-hero-split-focus);outline-offset:var(--aha-space-2)}
.aha-header-section-hero-split__hint{margin-top:var(--aha-space-12);font-size:var(--aha-size-default);line-height:var(--aha-line-height-body);color:var(--aha-header-section-hero-split-ink-secondary)}
.aha-header-section-hero-split__media{display:block;min-width:0}
.aha-header-section-hero-split__image{
  display:block;width:100%;height:auto;object-fit:cover;
  border-radius:var(--aha-radius-xl);background:var(--aha-header-section-hero-split-media-bg);
}
@container aha-header-section-hero-split (max-width:991px){
  .aha-header-section-hero-split__split{grid-template-columns:minmax(0,1fr)}
  .aha-header-section-hero-split__title{font-size:var(--aha-size-h3)}
  .aha-header-section-hero-split__text{font-size:var(--aha-size-l)}
}
@container aha-header-section-hero-split (max-width:767px){
  .aha-header-section-hero-split__inner{--aha-web-gutter:var(--aha-space-24);padding-inline:var(--aha-web-gutter)}
}
@container aha-header-section-hero-split (max-width:479px){
  .aha-header-section-hero-split__inner{--aha-web-gutter:var(--aha-space-16)}
  .aha-header-section-hero-split__actions,.aha-header-section-hero-split__form{margin-top:var(--aha-space-24)}
  .aha-header-section-hero-split__title{font-size:var(--aha-size-h4)}
  .aha-header-section-hero-split__actions{width:100%}
  .aha-header-section-hero-split__actions aha-button,.aha-header-section-hero-split__form aha-button{flex:1 1 100%}
}
.aha-header-section-hero-split__visually-hidden{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
.aha-header-section-hero-split--bleed .aha-header-section-hero-split__media{margin-right:calc(-1 * (var(--aha-space-32) + max(0px,(100cqw - 1280px) / 2)))}
.aha-header-section-hero-split--bleed .aha-header-section-hero-split__image{border-radius:var(--aha-radius-xl) 0 0 var(--aha-radius-xl)}
@container aha-header-section-hero-split (max-width:991px){
  .aha-header-section-hero-split--bleed .aha-header-section-hero-split__media{margin-right:0}
  .aha-header-section-hero-split--bleed .aha-header-section-hero-split__image{border-radius:var(--aha-radius-xl)}
}
.aha-header-section-hero-split--brand{position:relative;isolation:isolate}
.aha-header-section-hero-split__splash{display:none}
.aha-header-section-hero-split--brand>.aha-header-section-hero-split__splash{display:block;position:absolute;inset:0;z-index:-1;overflow:hidden;container-type:size;pointer-events:none;border-radius:inherit;--aha-header-section-hero-split-splash-width:calc(4.5*min(100cqw,100cqh)*sqrt(max(1,tan(atan2(100cqw,100cqh))*9/16,9/16/tan(atan2(100cqw,100cqh)))))}
.aha-header-section-hero-split__splash-icon{position:absolute;display:block;max-width:none;height:auto;width:var(--aha-header-section-hero-split-splash-width);left:calc(var(--aha-header-section-hero-split-splash-across)*100cqw - var(--aha-header-section-hero-split-splash-width)*0.516209);top:calc(55cqh - var(--aha-header-section-hero-split-splash-width)*0.418953)}
.aha-header-section-hero-split__splash{--aha-header-section-hero-split-splash-across:.75}
.aha-header-section-hero-split__image{aspect-ratio:5 / 4}

